import{_ as i,c as a,o as t,a2 as e}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"getPortfolio","description":"Storage-independent, note-free portfolio including pending-only assets and recovery ownership.","frontmatter":{"editLink":false,"rawMarkdown":"# getPortfolio\\n\\nStorage-independent, note-free portfolio including pending-only assets and recovery ownership.\\n\\n## Import\\n\\n```ts\\nimport { getPortfolio } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await getPortfolio({ config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getPortfolio(parameters?: GetPortfolioParameters): Promise<PortfolioSnapshot>\\n```\\n\\n## Returns\\n\\n`Promise<PortfolioSnapshot>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account whose portfolio is built. Defaults to the active account.\\n\\n```ts\\nconst result = await getPortfolio({\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `inputFinalityPolicy`\\n\\n- **Type:** `InputFinalityPolicy`\\n- **Required:** no\\n\\nWhich balance buckets count as spendable.\\n\\n```ts\\nconst result = await getPortfolio({\\n  inputFinalityPolicy: \\"finalized\\", // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the read.\\n\\n```ts\\nconst result = await getPortfolio({\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `priceMaxAgeMs`\\n\\n- **Type:** `number`\\n- **Required:** no\\n\\nHost freshness policy; defaults to five minutes.\\n\\n```ts\\nconst result = await getPortfolio({\\n  priceMaxAgeMs, // [!code focus]\\n});\\n```\\n\\n### `balanceMaxAgeMs`\\n\\n- **Type:** `number`\\n- **Required:** no\\n\\nHow old balance data may be before it is refreshed.\\n\\n```ts\\nconst result = await getPortfolio({\\n  balanceMaxAgeMs, // [!code focus]\\n});\\n```\\n\\n### `metadataMaxAgeMs`\\n\\n- **Type:** `number`\\n- **Required:** no\\n\\nRegistry metadata freshness policy; defaults to thirty minutes.\\n\\n```ts\\nconst result = await getPortfolio({\\n  metadataMaxAgeMs, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getPortfolio({\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/getPortfolio.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/getPortfolio.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/getPortfolio.md","rawMarkdownTitle":"getPortfolio","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/getPortfolio.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"getPortfolio"},"relativePath":"sdk/actions/views/getPortfolio.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/getPortfolio.md"};function o(l,s,r,h,p,d){return t(),a("div",null,[...s[0]||(s[0]=[e("",46)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
